<?php
function aliLaborFlag($value){if(!in_array($value,[0,1,'0','1',false,true],true))throw new InvalidArgumentException('La opción de mano de obra debe ser un check válido.');return (int)(bool)$value;}
function aliLaborEnrich($db,$data){$ids=[];$collect=function($node)use(&$collect,&$ids){if(!is_array($node))return;if(isset($node['IdProducto'])&&is_numeric($node['IdProducto']))$ids[(int)$node['IdProducto']]=(int)$node['IdProducto'];foreach($node as $child)if(is_array($child))$collect($child);};$collect($data);if(!$ids)return $data;$flags=[];foreach(array_chunk(array_values($ids),500) as $chunk){$s=$db->prepare('SELECT IdProducto,EsServicioManoObra FROM Gen_Producto WHERE IdProducto IN ('.implode(',',array_fill(0,count($chunk),'?')).')');$s->execute($chunk);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $row)$flags[(int)$row['IdProducto']]=(int)$row['EsServicioManoObra'];}$apply=function($node)use(&$apply,$flags){if(!is_array($node))return $node;if(isset($node['IdProducto'])&&isset($flags[(int)$node['IdProducto']]))$node['EsServicioManoObra']=$flags[(int)$node['IdProducto']];foreach($node as $key=>$child)if(is_array($child))$node[$key]=$apply($child);return $node;};return $apply($data);}
function aliRegisterLaborProducts($app){$app->add(function($q,$r,$next)use($app){$path='/'.ltrim($q->getUri()->getPath(),'/');$body=$q->getParsedBody()?:[];$saving=$q->getMethod()==='POST'&&preg_match('~(?:^|/)productos$~',$path)&&array_key_exists('EsServicioManoObra',$body);$flag=null;if($saving){try{$flag=aliLaborFlag($body['EsServicioManoObra']);if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=$_SESSION['user']??'';$expired=isset($_SESSION['expire'])&&$_SESSION['expire']<time();session_write_close();if(!$user||$expired)return $r->withJson(['error'=>'Inicia sesión antes de guardar el producto.'],401);$pos=aliPosCapabilities($app->getContainer()['db'],$user);if(!aliKnowledgeCanEdit($app->getContainer()['db'],$q->withAttribute('ali_user',$user)->withAttribute('ali_pos',$pos)))return $r->withJson(['error'=>'No tienes permiso para configurar este producto.'],403);if($flag){$body['OpcContable']=2;$body['EsServicio']=1;$body['EsMercaderia']=0;$body['ControlaStock']=0;$q=$q->withParsedBody($body);}}catch(InvalidArgumentException $e){return $r->withJson(['error'=>$e->getMessage()],422);}}
 $response=$next($q,$r);if($response->getStatusCode()!==200)return $response;$json=json_decode((string)$response->getBody(),true);if(!is_array($json))return $response;
 if($saving&&!isset($json['error'])&&!empty($json['insertId'])){$s=$app->getContainer()['db']->prepare('UPDATE Gen_Producto SET EsServicioManoObra=? WHERE IdProducto=?');$s->execute([$flag,(int)$json['insertId']]);}
 if($q->getMethod()==='GET'&&preg_match('~(?:^|/)(?:productos|proformas|preorden)(?:/|$)~',$path))return $response->withJson(aliLaborEnrich($app->getContainer()['db'],$json));return $response;
});}
